CREATE TABLE user_profile (id INTEGER PRIMARY KEY CHECK(id=1), display_name TEXT NOT NULL, instruments TEXT NOT NULL, primary_instrument TEXT NOT NULL, other_instrument_label TEXT, experience_level TEXT, musical_roles TEXT NOT NULL DEFAULT '[]', ensemble_name TEXT, onboarded_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE repertoire_items (id TEXT PRIMARY KEY, title TEXT NOT NULL, composer TEXT, movement TEXT, instrument TEXT, notes TEXT, archived_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE score_documents (id TEXT PRIMARY KEY, repertoire_item_id TEXT NOT NULL REFERENCES repertoire_items(id) ON DELETE CASCADE, label TEXT NOT NULL, relative_path TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL UNIQUE, original_name TEXT NOT NULL, original_path TEXT, size_bytes INTEGER NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, last_page INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE study_goals (id TEXT PRIMARY KEY, repertoire_item_id TEXT NOT NULL REFERENCES repertoire_items(id) ON DELETE CASCADE, description TEXT NOT NULL, target_bpm INTEGER, measure_start INTEGER, measure_end INTEGER, completed_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE study_sessions (id TEXT PRIMARY KEY, repertoire_item_id TEXT NOT NULL REFERENCES repertoire_items(id) ON DELETE RESTRICT, goal_id TEXT REFERENCES study_goals(id) ON DELETE SET NULL, status TEXT NOT NULL CHECK(status IN ('ACTIVE','PAUSED','FINISHED')), started_at INTEGER NOT NULL, ended_at INTEGER, active_ms INTEGER NOT NULL DEFAULT 0, resumed_at INTEGER, last_heartbeat_at INTEGER NOT NULL, initial_bpm INTEGER, final_bpm INTEGER, notes TEXT);
CREATE TABLE recordings (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES study_sessions(id) ON DELETE CASCADE, relative_path TEXT NOT NULL UNIQUE, format TEXT NOT NULL DEFAULT 'wav-pcm16-mono', status TEXT NOT NULL CHECK(status IN ('RECORDING','COMPLETE')), duration_ms INTEGER, sample_rate INTEGER, bpm INTEGER, title TEXT NOT NULL, notes TEXT, created_at INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX ix_scores_item ON score_documents(repertoire_item_id, sort_order);
CREATE INDEX ix_sessions_item_started ON study_sessions(repertoire_item_id, started_at DESC);
CREATE UNIQUE INDEX ux_single_open_session ON study_sessions(ended_at) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX ux_single_active_take ON recordings(status) WHERE status='RECORDING';
